<?php
/** Member 2, Feature 3 - Fabric Inspection directory. */
require_once __DIR__ . '/../../includes/auth.php';
require_role(['admin', 'production_manager', 'qc_officer']);
$pageTitle = 'Fabric Inspection'; $currentNav = 'fabric_inspections';
$search = trim($_GET['q'] ?? ''); $status = trim($_GET['status'] ?? 'all');
$allowed = ['Passed', 'Failed', 'Conditionally Approved'];
$where = []; $types = ''; $params = [];
if ($search !== '') { $where[] = '(fl.lot_number LIKE ? OR fl.fabric_type LIKE ? OR s.supplier_name LIKE ?)'; $w = '%' . $search . '%'; $types .= 'sss'; $params = [$w,$w,$w]; }
if (in_array($status, $allowed, true)) { $where[] = 'fi.result = ?'; $types .= 's'; $params[] = $status; }
$sql = "SELECT fi.*, fl.lot_number, fl.fabric_type, fl.color, fl.unit, s.supplier_name, u.full_name inspector_name, u.username inspector_username FROM fabric_inspections fi JOIN fabric_lots fl ON fl.fabric_lot_id=fi.fabric_lot_id JOIN suppliers s ON s.supplier_id=fl.supplier_id JOIN users u ON u.user_id=fi.inspector_id";
if ($where) $sql .= ' WHERE ' . implode(' AND ', $where);
$sql .= ' ORDER BY fi.fabric_inspection_id DESC';
$rows=[];
try { $stmt=$conn->prepare($sql); if(!$stmt) throw new Exception($conn->error); if($types!=='')$stmt->bind_param($types,...$params); $stmt->execute(); $rows=$stmt->get_result()->fetch_all(MYSQLI_ASSOC); $stmt->close(); } catch(Throwable $e){ error_log('Fabric inspection list failed: '.$e->getMessage()); flash_set('error','Inspection records could not be loaded. Import sql/fabric_inspections.sql if the table is not installed.'); }
include __DIR__.'/../../includes/header.php'; include __DIR__.'/../../includes/sidebar.php';
?>
<div class="page-header"><div class="page-title-group"><h1>Fabric Inspection</h1><div class="page-subtitle">Member 2 &bull; Inspect received fabric before allocation</div></div><div class="page-actions"><a class="btn btn-primary" href="<?=e(url('modules/fabric_inspections/create.php'))?>">Record Inspection</a><a class="btn btn-secondary" href="<?=e(url('modules/fabric_receiving/index.php'))?>">Receiving List</a></div></div>
<div class="card mb-4"><div class="card-body"><form method="get" class="filter-bar"><div class="filter-field-grow"><label class="form-label" for="q">Search</label><input class="form-control" id="q" name="q" value="<?=e($search)?>" placeholder="Lot, fabric type, or supplier"></div><div class="filter-field"><label class="form-label" for="status">Result</label><select class="form-control" id="status" name="status"><option value="all">All Results</option><?php foreach($allowed as $v):?><option value="<?=e($v)?>" <?=$status===$v?'selected':''?>><?=e($v)?></option><?php endforeach?></select></div><div class="filter-actions"><button class="btn btn-primary">Filter</button><?php if($search!==''||$status!=='all'):?><a class="btn btn-secondary" href="<?=e(url('modules/fabric_inspections/index.php'))?>">Clear</a><?php endif?></div></form></div></div>
<div class="card"><div class="card-header"><h2>Inspection History</h2><span class="badge badge-muted"><?=count($rows)?> Record(s)</span></div><div class="card-body" style="padding:0"><?php if(!$rows):?><div class="empty-state"><p>No fabric inspections found.</p><a class="btn btn-primary btn-sm" href="<?=e(url('modules/fabric_inspections/create.php'))?>">Record First Inspection</a></div><?php else:?><div class="table-responsive"><table class="table"><thead><tr><th>Lot</th><th>Supplier</th><th>Date</th><th>Inspected</th><th>Points</th><th>Result</th><th>Inspector</th><th>Action</th></tr></thead><tbody><?php foreach($rows as $r): $badge=$r['result']==='Passed'?'badge-success':($r['result']==='Failed'?'badge-danger':'badge-warning');?><tr><td><strong><?=e($r['lot_number'])?></strong><div class="text-xs text-muted"><?=e($r['fabric_type'])?><?= $r['color']?' &bull; '.e($r['color']):''?></div></td><td><?=e($r['supplier_name'])?></td><td><?=e(date('M d, Y',strtotime($r['inspection_date'])))?></td><td><?=number_format((float)$r['inspected_quantity'],2)?> <?=e($r['unit'])?></td><td><?=(int)$r['penalty_points']?></td><td><span class="badge <?=$badge?>"><?=e($r['result'])?></span></td><td><?=e($r['inspector_name']?:$r['inspector_username'])?></td><td><a class="btn btn-sm btn-secondary" href="<?=e(url('modules/fabric_inspections/view.php?id='.(int)$r['fabric_inspection_id']))?>">View</a></td></tr><?php endforeach?></tbody></table></div><?php endif?></div></div>
<?php echo '<link rel="stylesheet" href="modern-ui.css">'; include __DIR__.'/../../includes/footer.php';
